{
  "items": [
    {
      "name": "Finset.sum_div",
      "module_name": "Mathlib.Algebra.BigOperators.Field",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {K : Type u_2} [inst : DivisionSemiring K] (s : Finset ι) (f : ι → K) (a : K),\n  (∑ i ∈ s, f i) / a = ∑ i ∈ s, f i / a"
    },
    {
      "name": "Nat.sum_div",
      "module_name": "Mathlib.Algebra.BigOperators.Ring.Finset",
      "kind": "theorem",
      "type": "∀ {ι : Type u_5} {s : Finset ι} {f : ι → ℕ} {n : ℕ}, (∀ i ∈ s, n ∣ f i) → (∑ i ∈ s, f i) / n = ∑ i ∈ s, f i / n"
    },
    {
      "name": "Multiset.sum_map_div",
      "module_name": "Mathlib.Algebra.BigOperators.Field",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {K : Type u_2} [inst : DivisionSemiring K] (s : Multiset ι) (f : ι → K) (a : K),\n  (Multiset.map (fun x => f x / a) s).sum = (Multiset.map f s).sum / a"
    },
    {
      "name": "Int.sum_div",
      "module_name": "Mathlib.Algebra.BigOperators.Ring.Finset",
      "kind": "theorem",
      "type": "∀ {ι : Type u_5} {s : Finset ι} {f : ι → ℤ} {n : ℤ}, (∀ i ∈ s, n ∣ f i) → (∑ i ∈ s, f i) / n = ∑ i ∈ s, f i / n"
    },
    {
      "name": "Sum.elim_div_div",
      "module_name": "Mathlib.Algebra.Group.Pi.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} {γ : Type u_3} (a a' : α → γ) (b b' : β → γ) [inst : Div γ],\n  Sum.elim (a / a') (b / b') = Sum.elim a b / Sum.elim a' b'"
    }
  ]
}
